  if(!trustedTwitch&&validateSourceLink(urlString).error)throw new Error(validateSourceLink(urlString).error);
  if(!trustedTwitch&&matchesHost(url.hostname,'twitch.tv'))throw new Error('Twitch watch pages are not downloadable. Import a Twitch Clip or send your own live stream directly to this app.');
  const addresses=isIP(url.hostname)?[{address:url.hostname,family:isIP(url.hostname)}]:await dnsLookup(url.hostname,{all:true,verbatim:true});
