  if(existing?.status==='complete')return {words:db.prepare('SELECT start,end,text FROM transcript_words WHERE project_id=? ORDER BY ordinal').all(project.id),configured:true};
  const apiKey=process.env.OPENAI_API_KEY;
  if(!apiKey)return {words:[],configured:false};
  db.prepare('INSERT INTO transcriptions(project_id,status,updated_at) VALUES(?,?,?) ON CONFLICT(project_id) DO UPDATE SET status=excluded.status,error=NULL,updated_at=excluded.updated_at').run(project.id,'processing',now());
